type DividerOrientation = 'horizontal' | 'vertical';

export type DividerProps = {
  orientation?: DividerOrientation;
  className?: string;
};

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export function Divider({
  orientation = 'horizontal',
  className,
}: DividerProps) {
  return (
    <hr
      className={cn('divider', `divider--${orientation}`, className)}
      role={orientation === 'vertical' ? 'separator' : undefined}
      aria-orientation={orientation === 'vertical' ? 'vertical' : undefined}
    />
  );
}

/* -------------------------------------------------------------------------
   Divider

   Horizontal or vertical separator line.
   Figma: atom-horizontal-divider. We add vertical variant.

   Orientation: horizontal (default), vertical
   ------------------------------------------------------------------------- */

.divider {
  border: none;
  margin: 0;
  flex-shrink: 0;
}

.divider--horizontal {
  width: 100%;
  height: 0;
  border-top: var(--stroke-hairline) solid var(--border);
}

.divider--vertical {
  height: 100%;
  width: 0;
  border-left: var(--stroke-hairline) solid var(--border);
  align-self: stretch;
}

/* ---- Labeled: etiqueta + linea que ocupa el resto (patron de seccion) ---- */

.divider--labeled {
  display: flex;
  align-items: center;
  gap: var(--spacing-3);
  width: 100%;
  height: auto;
  border: none;
  color: var(--muted-foreground);
}

.divider--labeled::after {
  flex: 1;
  height: var(--stroke-hairline);
  content: '';
  background-color: currentcolor;
  opacity: 0.15;
}
